function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 1 || grid.length > 100) return 'grid needs 1 to 100 rows.';
  const n = Array.isArray(grid[0]) ? grid[0].length : 0;
  if (n < 1 || n > 100) return 'grid needs 1 to 100 columns.';
  for (const row of grid) {
    if (!Array.isArray(row) || row.length !== n) return 'Every row must have the same length.';
    if (row.some(ch => ch !== '(' && ch !== ')')) return "Each cell is '(' or ')'.";
  }
  return null;
}

