function hasValidPath(grid) {
  const rows = grid.length;
  const cols = grid[0].length;
  const steps = rows + cols - 1;
  if (steps % 2 === 1 || grid[0][0] === ')' || grid[rows - 1][cols - 1] === '(') {
    return false;
  }
  // dp[r][c][b] is 1 when some path to (r, c) never dips below zero and ends with balance b.
  const dp = Array.from({ length: rows }, () => Array.from({ length: cols }, () => new Uint8Array(steps + 1)));
  dp[0][0][1] = 1;

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (r === 0 && c === 0) {
        continue;
      }
      const delta = grid[r][c] === '(' ? 1 : -1;
      const remaining = (rows - 1 - r) + (cols - 1 - c);
      for (let balance = 0; balance <= steps; balance++) {
        const fromUp = r > 0 && dp[r - 1][c][balance] === 1;
        const fromLeft = c > 0 && dp[r][c - 1][balance] === 1;
        if (!fromUp && !fromLeft) {
          continue;
        }
        const next = balance + delta;
        if (next >= 0 && next <= remaining) {
          dp[r][c][next] = 1;
        }
      }
    }
  }
  return dp[rows - 1][cols - 1][0] === 1;
}

