function hasValidPath(grid) {
  const m = grid.length, n = grid[0].length;
  const valid = text => {
    let depth = 0;
    for (const ch of text) {
      depth += ch === '(' ? 1 : -1;
      if (depth < 0) return false;
    }
    return depth === 0;
  };
  const walk = (i, j, text) => {
    const here = text + grid[i][j];
    if (i === m - 1 && j === n - 1) return valid(here);
    return (i + 1 < m && walk(i + 1, j, here)) || (j + 1 < n && walk(i, j + 1, here));
  };
  return walk(0, 0, '');
}

