function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const rows = size === 'large' ? pick(80, 100) : pick(1, 5);
  let cols = size === 'large' ? pick(80, 100) : pick(1, 5);
  // Most cases get an even path length so that the answer is not decided by parity alone.
  if ((rows + cols - 1) % 2 === 1 && rand() < 0.8) cols = cols > 1 ? cols - 1 : cols + 1;
  const bias = 0.35 + rand() * 0.3;
  const grid = Array.from({ length: rows }, () => Array.from({ length: cols }, () => (rand() < bias ? '(' : ')')));
  const steps = rows + cols - 1;
  if (steps % 2 === 0 && rand() < 0.5) {
    // Plant a valid parentheses string along one random monotone path.
    const moves = [...Array(rows - 1).fill('D'), ...Array(cols - 1).fill('R')];
    for (let i = moves.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [moves[i], moves[j]] = [moves[j], moves[i]];
    }
    let r = 0, c = 0, depth = 0;
    for (let i = 0; i < steps; i++) {
      const left = steps - i;
      const open = depth === 0 || (depth < left && rand() < 0.5);
      grid[r][c] = open ? '(' : ')';
      depth += open ? 1 : -1;
      if (i < moves.length) {
        if (moves[i] === 'D') r++;
        else c++;
      }
    }
  }
  return [grid];
}
